<template>
  <div class="page-title"><div><p class="eyebrow">SCENARIO STUDIO</p><h1>Turn a process into practice</h1></div><button @click="create">New scenario</button></div>
  <div class="studio-layout"><aside class="card"><h2>Your scenarios</h2><button class="scenario-link" v-for="s in workspace.scenarios" :key="s.name" @click="load(s.name)">{{ s.title }}<small>{{ s.published_version ? 'Published · draft ' : 'Draft ' }}{{ s.draft_revision }}</small></button><p v-if="!workspace.scenarios.length">Create your first scenario to get started.</p></aside>
  <form v-if="content" class="card studio" @submit.prevent="saveDraft">
    <div class="toolbar"><span>{{ name ? 'Draft revision '+revision : 'New draft' }}{{ dirty ? ' · Unsaved changes' : '' }}</span><button type="button" :disabled="busy" @click="exportDocument">Export SOP</button><button :disabled="busy">Save draft</button><button type="button" :disabled="busy || dirty || !name" @click="publishDraft">Publish saved draft</button></div>
    <p role="status">{{ message }}</p>
    <div class="form-grid"><label>Scenario title<input required maxlength="200" v-model="content.title"></label><label>Process<select v-model="process" :disabled="Boolean(name)"><option value="">Company-wide</option><option v-for="p in workspace.processes" :key="p.name" :value="p.name">{{ p.title }}</option></select></label><label>Office<select v-model="content.office" @change="setRubric"><option value="back">Back office</option><option value="front">Front office</option></select></label><label>Pass threshold<input type="number" min="1" max="100" v-model.number="content.threshold"></label></div>
    <label>Learner brief<textarea required v-model="content.brief"></textarea></label><label>Reference instructions<textarea required rows="5" v-model="content.reference"></textarea></label><label>Expected outcome<textarea required v-model="content.outcome"></textarea></label>
    <div v-if="content.office === 'front'" class="form-grid"><label>Customer name<input v-model="content.customerName"></label><label>Customer persona<textarea v-model="content.persona"></textarea></label><label>Opening message<textarea v-model="content.opening"></textarea></label></div>
    <h2>Assessment rubric</h2><div class="form-grid"><label v-for="r in content.rubric" :key="r.key">{{ r.label }} weight<input type="number" min="0.01" max="100" step="0.01" v-model.number="r.weight"><textarea :aria-label="r.label+' grading guidance'" placeholder="Grading guidance" v-model="r.guidance"></textarea></label></div>
    <div class="section-heading"><h2>Screenshot steps</h2><button type="button" @click="addStep">Add step</button></div>
    <article v-for="(step,index) in content.steps" :key="step.id" class="step-editor">
      <div class="section-heading"><h3>Step {{ index+1 }}</h3><div><button type="button" :disabled="index===0" @click="move(index,-1)">Move up</button><button type="button" :disabled="index===content.steps.length-1" @click="move(index,1)">Move down</button><button type="button" @click="content.steps.splice(index,1)">Remove</button></div></div>
      <label>Step title<input v-model="step.title"></label><label>Instructions<textarea v-model="step.instructions"></textarea></label><label>Practice hint<input v-model="step.hint"></label><label><input type="checkbox" v-model="step.critical">Required critical step</label>
      <label>Screenshot<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,step)"></label>
      <div v-if="urls[step.assetId]" class="screenshot-editor" @pointerdown="beginDraw($event,step)" @pointerup="endDraw($event,step)"><img :src="urls[step.assetId]" alt="Procedure screenshot; drag to draw an action region" draggable="false"><span v-for="h in step.hotspots" :key="h.id" class="region" :style="regionStyle(h)">{{ h.label }}</span></div>
      <p class="muted">Drag across the screenshot to add a region, or add one below. Coordinates are proportions from 0 to 1.</p><button type="button" @click="addHotspot(step)">Add action region</button>
      <div v-for="h in step.hotspots" :key="h.id" class="hotspot-form"><div class="form-grid"><label>Action label<input v-model="h.label"></label><label>Action type<select v-model="h.type"><option value="click">Click</option><option value="input">Input</option></select></label><label v-for="key in ['x','y','w','h']" :key="key">{{ key }}<input type="number" min="0" max="1" step="0.005" v-model.number="h[key]"></label></div><label><input type="checkbox" v-model="h.correct">Required correct action</label><label><input type="checkbox" v-model="h.critical">Incorrect action is a critical failure</label><label v-if="h.type==='input'">Accepted answers (one per line)<textarea :value="h.accepted.join('\n')" @input="h.accepted=$event.target.value.split('\n')"></textarea></label><button type="button" @click="step.hotspots.splice(step.hotspots.indexOf(h),1)">Remove action</button></div>
    </article>
    <h2>Preview</h2><p>Walkthrough shows instructions, hints and correct actions. Assessment hides them.</p><select v-model="preview"><option>walkthrough</option><option>assessment</option></select><article v-if="content.steps.length" class="preview"><h3>{{ preview==='assessment'?'Screen 1':content.steps[0].title }}</h3><p v-if="preview!=='assessment'">{{ content.steps[0].instructions }}</p><div class="screenshot-editor" v-if="urls[content.steps[0].assetId]"><img :src="urls[content.steps[0].assetId]" alt="Scenario preview"><span v-for="h in content.steps[0].hotspots" :key="h.id" class="region" :style="regionStyle(h)">{{ h.label }}{{ preview==='walkthrough'&&h.correct?' ✓':'' }}</span></div></article>
  </form><div v-else class="empty">Choose a scenario or create a new one.</div></div>
</template>
<script setup>
import { computed, reactive, ref } from 'vue'
import { api, screenshotUrl } from '../lib/api'
import { exportSop } from '../lib/export-sop'
const props=defineProps(['workspace']);const emit=defineEmits(['changed','error'])
const name=ref(''),revision=ref(0),process=ref(''),content=ref(null),saved=ref(''),message=ref(''),busy=ref(false),urls=reactive({}),preview=ref('walkthrough')
const dirty=computed(()=>JSON.stringify(content.value)!==saved.value)
const regionStyle=h=>({left:h.x*100+'%',top:h.y*100+'%',width:h.w*100+'%',height:h.h*100+'%'})
function setRubric(){content.value.rubric=['procedure','resolution','compliance',...(content.value.office==='front'?['communication']:[])].map(key=>({key,label:key[0].toUpperCase()+key.slice(1),weight:1,guidance:''}))}
function create(){name.value='';revision.value=0;process.value=props.workspace.processes[0]?.name||'';content.value={title:'New scenario',office:'back',brief:'',reference:'',outcome:'',customerName:'',persona:'',opening:'',threshold:80,rubric:[],steps:[]};setRubric();saved.value='';message.value=''}
function addStep(){content.value.steps.push({id:crypto.randomUUID(),title:'',instructions:'',hint:'',assetId:'',critical:false,hotspots:[]})}
function addHotspot(step,rect={x:.25,y:.25,w:.2,h:.1}){step.hotspots.push({id:crypto.randomUUID(),label:'Action',type:'click',accepted:[],correct:true,critical:false,...rect})}
function move(i,delta){const s=content.value.steps;[s[i],s[i+delta]]=[s[i+delta],s[i]]}
let draw=null
function beginDraw(e,step){if(e.button!==0)return;e.currentTarget.setPointerCapture(e.pointerId);const r=e.currentTarget.getBoundingClientRect();draw={step:step.id,x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}
function endDraw(e,step){if(!draw||draw.step!==step.id)return;const r=e.currentTarget.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));const rect={x:Math.min(x,draw.x),y:Math.min(y,draw.y),w:Math.abs(x-draw.x),h:Math.abs(y-draw.y)};draw=null;if(rect.w>=.005&&rect.h>=.005)addHotspot(step,rect)}
async function load(id){try{if(dirty.value&&content.value&&!confirm('Discard unsaved changes?'))return;const s=await api('get_scenario',{name:id});name.value=s.name;revision.value=s.revision;process.value=s.process||'';content.value=s.content;saved.value=JSON.stringify(s.content);for(const step of s.content.steps)if(step.assetId)urls[step.assetId]=await screenshotUrl(step.assetId)}catch(e){emit('error',e)}}
async function saveDraft(){busy.value=true;try{const s=await api('save_scenario',{name:name.value||null,revision:revision.value,process:process.value||null,company_wide:process.value?0:1,content:content.value});name.value=s.name;revision.value=s.revision;saved.value=JSON.stringify(content.value);message.value='Draft saved';emit('changed')}catch(e){emit('error',e)}finally{busy.value=false}}
async function publishDraft(){busy.value=true;try{const v=await api('publish',{name:name.value,revision:revision.value});message.value='Published immutable version '+v.number;emit('changed')}catch(e){emit('error',e)}finally{busy.value=false}}
async function upload(event,step){const file=event.target.files[0];if(!file)return;busy.value=true;try{const form=new FormData();form.set('process',process.value);form.set('company_wide',process.value?'0':'1');form.set('file',file);const a=await api('upload_asset',form);step.assetId=a.name;urls[a.name]=a.url}catch(e){emit('error',e)}finally{busy.value=false;event.target.value=''}}
async function exportDocument(){busy.value=true;try{const p=props.workspace.processes.find(p=>p.name===process.value);await exportSop({content:content.value,revision:revision.value,unsaved:dirty.value,process:p?{name:p.title,client:p.client}:undefined})}catch(e){emit('error',e)}finally{busy.value=false}}
</script>
